mapper.select:
SELECT l.id, l.location_id AS locationId, l.location_code AS locationCode, l.location_name AS locationName, l.node_id AS nodeId, n.node_name AS nodeName, l.location_level AS locationLevel, l.location_type AS locationType, l.max_capacity AS maxCapacity, l.current_quantity AS currentQuantity, l.location_status AS locationStatus, l.remark, l.create_time AS createTime FROM spd_location l LEFT JOIN spd_org_node n ON l.node_id = n.node_id AND n.del_flag = 0 WHERE l.del_flag = 0
AND l.location_code LIKE CONCAT('%', #{form.locationCode}, '%')
AND l.location_name LIKE CONCAT('%', #{form.locationName}, '%')
AND l.node_id = #{form.nodeId}
AND l.location_status = #{form.locationStatus}
ORDER BY l.create_time DESC
